/*
 * MST_$MAP_AREA - create a VM area and map it in the current address space
 *
 * Original address: 0x00E43B3A (SAU2 map: MST_$MAP_AREA at E43B3A)
 * Size: 202 bytes (0x00E43B3A .. 0x00E43C03)
 * Generated by: Claude Opus 5.5
 *
 * SVC slot 0x01 (svc/svc_tables.c; DATA xref 0x00E7BAF6), every argument
 * by reference.  Frame (link.w A6,-0x20; D2/A2-A5 saved; A5 = 0xE7CF0C,
 * MST_UNWIRED, never used):
 *   (0x08,A6) virt_size_ptr (A2), (0x0C) commit_size_ptr,
 *   (0x10) reversed_ptr -> Domain boolean (A4), (0x14) uid_out,
 *   (0x18) status (A3)
 *   locals: (-0x08) the area UID, (-0x0C) the area handle, (-0x10) the
 *   delete status, (-0x14) the mapped VA, (-0x18) map_info, (-0x1C) the
 *   object offset, (-0x20) the result.
 *
 * Blocks:
 *   0x00E43B54-0x00E43B72  AREA_$CREATE; its handle comes back in D0
 *   0x00E43B76-0x00E43B96  UID = {ANON_$UID.high, handle}; a reversed area
 *                          is mapped from offset 0x7FFFFFFF - (size - 1)
 *   0x00E43B9A-0x00E43BCA  mst_$alloc_segs at the private top, area id 7,
 *                          touch count 1
 *   0x00E43BCE-0x00E43BF0  a failed map deletes the area; a good one hands
 *                          out the UID
 *
 * Quirk reproduced: when AREA_$CREATE fails the routine returns (-0x20,A6)
 * without having written it (0x00E43B72 bne 0x00E43BF6): the A0 result is
 * whatever the frame slot held.  ORIGINAL BUG; left indeterminate here
 * (source-tyqa).
 */

#include "mst/mst_internal.h"
#include "anon/anon.h"

/* mst_$alloc_segs arguments: `move.l #0x7fffffff` 0x00E43BBC and
 * `move.l #0x70001` 0x00E43BA4 (area id 7, touch count 1) */
#define MST_MAP_AREA_ADDR_HINT  0x7FFFFFFFu
#define MST_MAP_AREA_AREA_ID    7
#define MST_MAP_AREA_TOUCH      1

void *MST_$MAP_AREA(uint32_t *virt_size_ptr, uint32_t *commit_size_ptr,
                    boolean *reversed_ptr, uid_t *uid_out, status_$t *status)
{
    uid_t uid;                  /* (-0x08,A6) */
    area_$handle_t handle;      /* (-0x0C,A6) */
    status_$t del_status;       /* (-0x10,A6) */
    void *va;                   /* (-0x14,A6) */
    uint32_t map_info;          /* (-0x18,A6) */
    uint32_t start;             /* (-0x1C,A6) */
    void *result;               /* (-0x20,A6) */

    /* 0x00E43B54-0x00E43B72 */
    handle = AREA_$CREATE(*virt_size_ptr, *commit_size_ptr, *reversed_ptr,
                          status);
    if (*status != status_$ok) {
        /* (-0x20,A6) deliberately returned unwritten (see the header);
         * an initialiser would be an invention, not a transcription. */
#if defined(__GNUC__)
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wuninitialized"
#endif
        return result;
#if defined(__GNUC__)
#pragma GCC diagnostic pop
#endif
    }

    /* 0x00E43B76-0x00E43B96 */
    uid.high = ANON_$UID.high;
    uid.low = handle;
    start = 0;
    if (*reversed_ptr < 0) {
        start = MST_MAP_AREA_ADDR_HINT - (*virt_size_ptr - 1);
    }

    /* 0x00E43B9A-0x00E43BCA */
    va = mst_$alloc_segs(MST_MAP_AREA_ADDR_HINT, &uid, start, *virt_size_ptr,
                         0, (int16_t)PROC1_$AS_ID, MST_MAP_AREA_AREA_ID,
                         MST_MAP_AREA_TOUCH, 0, false, &map_info, status);

    /* 0x00E43BCE-0x00E43BF0 */
    if (*status != status_$ok) {
        AREA_$DELETE(handle, &del_status);
    } else {
        *uid_out = uid;
    }
    result = va;
    return result;
}
